拼接目录链接<js>
base="https://www.po18.xyz/read/";
try{
$=result.match(/(\d+),(\d+)\)/)
url=base+$[2]+"/"+$[1]+"/";
}catch(error){
	try{
$=result.match(/(\d+)\/(\d+)\/$/)
url=base+$[1]+"/"+$[2]+"/";
}catch(anotherError){
	url="。。";
}
}
url;
</js>
